  v = {'code': q(s['code']), 'title': q(s['title']), 'unit': q(s['unit']), 'cat': q(s['cat']), 'icon': q(s['icon']), 'status': q(s.get('status', 'draft')), 'sort': str(s.get('sort', 0)),
       'keywords': A(s.get('keywords', [])), 'summary': q(s.get('summary', '')), 'facts': J(s.get('facts', [])), 'routes': J(s.get('routes', [])), 'flow': J(s.get('flow', [])),
       'raci': J(s.get('raci', {})), 'coord': J(s.get('coord', [])), 'sections': J(s.get('sections', [])), 'links': J(s.get('links', {})), 'confirm': A(s.get('confirm', []))}
  return f"  insert into public.services({','.join(cols)}) values ({','.join(v[c] for c in cols)}) on conflict (code) do nothing;"
